write_json(result,file.path(out,'relative-locus-CN-results.json'),pretty=TRUE,auto_unbox=TRUE,na='null',digits=16);cat('EMC_MTAP_RELATIVE_CN_BEGIN\n');cat(toJSON(result,auto_unbox=TRUE,na='null',digits=16));cat('\nEMC_MTAP_RELATIVE_CN_END\n');if(length(errors))quit(status=2)
